package com.oms.supplychain.service.wms;

import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

class ReturnDocumentReadTest {
    SharedReturnParcelsTest f;ReturnDocumentRead read;ReturnQueryWarehouse query;
    @BeforeEach void setup(){f=new SharedReturnParcelsTest();f.setup();for(String t:Arrays.asList("wms_refund_parcel_receipt","wms_refund_parcel_document","wms_refund_parcel_member","wms_refund_parcel"))f.f.jdbc.update("DELETE FROM "+t);read=new ReturnDocumentRead();read.db=f.f.db;read.routes=mock(WmsTenantRoutes.class);query=new ReturnQueryWarehouse();query.db=f.f.db;query.routes=mock(WmsTenantRoutes.class);}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> x){return (List<Map<String,Object>>)x.get("rows");}
    @Test void commonDocumentHasTwoSourcesAndOnlyOneOriginalReceipt(){long event=f.receipt(true,f.line("A",String.valueOf(f.exchangeMember),4,1),f.line("G",String.valueOf(f.refundMember),3,0));f.parcels.allocate("QM",f.parcel,event,Collections.emptyMap(),true);clearInvocations(f.f.inventory);Map<String,Object> summary=read.read("QM","THKX_TEST","SUMMARY",1,20);assertEquals(2,((List<?>)summary.get("sources")).size());Map<String,Object> receipts=read.read("QM","THKX_TEST","RECEIPTS",1,20);assertEquals(1,id(receipts.get("total")));assertEquals(true,rows(receipts).get(0).get("final_confirmation"));assertEquals(2,((List<?>)rows(receipts).get(0).get("lines")).size());assertFalse(rows(receipts).get(0).containsKey("payload"));List<Map<String,Object>> allocations=(List<Map<String,Object>>)rows(receipts).get(0).get("allocations");assertEquals(new HashSet<>(Arrays.asList("HH_TEST","TK_TEST")),new HashSet<>(Arrays.asList(allocations.get(0).get("owner_sn"),allocations.get(1).get("owner_sn"))));assertFalse(rows(receipts).get(0).get("create_time").toString().contains("T"));verifyNoInteractions(f.f.inventory);}
    @Test void stockLinesKeepEachSourceCostGradesAndRealInventoryReference(){long event=f.receipt(true,f.line("A",String.valueOf(f.exchangeMember),4,1),f.line("G",String.valueOf(f.refundMember),3,0));f.parcels.allocate("QM",f.parcel,event,Collections.emptyMap(),true);clearInvocations(f.f.inventory);Map<String,Object> lines=read.read("QM","THKX_TEST","LINES",1,20);assertEquals(2,id(lines.get("total")));for(Map<String,Object> l:rows(lines)){assertEquals(1,id(l.get("posted")));assertTrue(text(l.get("inventory_relation")).startsWith("REFUND".equals(l.get("owner_kind"))?"REFUND_RETURN_":"EXCHANGE_RETURN_"));assertEquals("ORIGINAL-RETURN",l.get("batch_code"));assertEquals("REFUND".equals(l.get("owner_kind"))?"3.750000":"2.500000",l.get("unit_cost").toString());}verifyNoInteractions(f.f.inventory);}
    @Test void finalShortUnallocatedReceiptIsVisibleWithoutInventingAcceptedStock(){f.receipt(true,f.line("A",String.valueOf(f.exchangeMember),2,0));Map<String,Object> receipts=read.read("QM","THKX_TEST","RECEIPTS",1,20);assertEquals("WAIT_ALLOCATION",rows(receipts).get(0).get("state"));assertEquals(0,id(read.read("QM","THKX_TEST","LINES",1,20).get("total")));for(Map<String,Object> r:query.snapshots("QM",Arrays.asList(map("owner_kind","EXCHANGE","source_id",1),map("owner_kind","REFUND","source_id",2))))assertEquals(1,id(r.get("receipt_difference")));verifyNoInteractions(f.f.inventory);}
    @Test void laterQueryFailureDoesNotOverwriteWarehouseAcceptedState(){long log=f.f.db.insert("wms_interaction_log",map("company_code","QM","connection_id",1,"ticket_sn","THKX_TEST","direction","OUT","action","AFTERSALE_RETURN_QUERY","request_id","READ_QUERY_FAIL","request_body","hidden","response_body","hidden","result","FAILED","error_info","query timeout"));List<Map<String,Object>> rs=query.snapshots("QM",Arrays.asList(map("owner_kind","EXCHANGE","source_id",1),map("owner_kind","REFUND","source_id",2)));for(Map<String,Object> r:rs){assertEquals("ACCEPTED",r.get("warehouse_state"));Map<?,?> interaction=(Map<?,?>)r.get("interaction");assertEquals(log,id(interaction.get("id")));assertEquals("FAILED",interaction.get("result"));assertFalse(interaction.containsKey("request_body"));}assertEquals(2,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_return_query_dirty WHERE company_code='QM' AND ((owner_kind='EXCHANGE' AND source_id=1) OR (owner_kind='REFUND' AND source_id=2))",Integer.class));verifyNoInteractions(f.f.inventory);}
    @Test void independentDocumentShowsOnlyItsOwnReceiptAndReview(){f.f.jdbc.update("DELETE FROM wms_shared_return_member");f.f.jdbc.update("DELETE FROM wms_shared_return_document");f.f.jdbc.update("UPDATE wms_exchange_return SET shared_member_id=NULL,return_sn='THX_READ_INDEPENDENT'");assertEquals(0,id(read.read("QM","THX_READ_INDEPENDENT","RECEIPTS",1,20).get("total")));assertEquals(0,id(read.read("QM","THX_READ_INDEPENDENT","REVIEWS",1,20).get("total")));assertEquals(1,((List<?>)read.read("QM","THX_READ_INDEPENDENT","SUMMARY",1,20).get("sources")).size());verifyNoInteractions(f.f.inventory);}
    @Test void paginationIsBoundedAndDoesNotRepeatSourceRows(){long event=f.receipt(true,f.line("A",String.valueOf(f.exchangeMember),5,0),f.line("G",String.valueOf(f.refundMember),3,0));f.parcels.allocate("QM",f.parcel,event,Collections.emptyMap(),true);Map<String,Object> a=read.read("QM","THKX_TEST","LINES",1,1),b=read.read("QM","THKX_TEST","LINES",2,1);assertEquals(2,id(a.get("total")));assertNotEquals(rows(a).get(0).get("owner_kind"),rows(b).get(0).get("owner_kind"));assertThrows(IllegalArgumentException.class,()->read.read("QM","THKX_TEST","LINES",1,51));}
    @Test void privateLedgerAndCrossCompanyRequestsCannotReadFacts(){assertThrows(IllegalArgumentException.class,()->read.read("QM","RSL_REFUND","SUMMARY",1,20));assertThrows(IllegalArgumentException.class,()->read.read("OTHER","THKX_TEST","LINES",1,20));assertThrows(IllegalArgumentException.class,()->read.read("QM","THKX_TEST","unknown",1,20));verifyNoInteractions(f.f.inventory);}
    @Test void pendingCancellationHasPriorityButKeepsConfirmedReceiptFacts(){assertEquals("CANCEL_PENDING",ReturnQueryWarehouse.warehouseState(map("dispatch_state","ACCEPTED","cancel_state","UNKNOWN")));assertEquals("CANCELED",ReturnQueryWarehouse.warehouseState(map("dispatch_state","CANCELED","cancel_state","CONFIRMED")));}
}
